102:Coin::update(float dt_sec)
103:{
104:  // If we have a path to follow, follow it.
105:  if (get_walker()) {
106:    Vector v(0.0f, 0.0f);
107:    if (m_from_tilemap)
108:    {
109:      v = m_offset + get_walker()->get_pos(m_col.m_bbox.get_size(), m_path_handle);
110:    }
111:    else
112:    {
113:      get_walker()->update(dt_sec);
114:      v = get_walker()->get_pos(m_col.m_bbox.get_size(), m_path_handle);
115:    }
116:
117:    if (get_path() && get_path()->is_valid()) {
118:      m_col.set_movement(v - get_pos());
119:    }
120:  }
121:}
