239:HitResponse
240:Coin::collision(MovingObject& other, const CollisionHit& )
241:{
242:  auto player = dynamic_cast<Player*>(&other);
243:  if (player == nullptr)
244:    return ABORT_MOVE;
245:  if (m_col.get_bbox().overlaps(player->get_bbox().grown(-0.1f)))
246:    collect();
247:  return ABORT_MOVE;
248:}
