322:ObjectSettings
323:Coin::get_settings()
324:{
325:  ObjectSettings result = MovingSprite::get_settings();
326:
327:  result.add_path_ref(_("Path"), *this, get_path_ref(), "path-ref");
328:  m_add_path = has_valid_path();
329:  result.add_bool(_("Following path"), &m_add_path);
330:
331:  if (m_add_path) {
332:    result.add_walk_mode(_("Path Mode"), &get_path()->m_mode, {}, {});
333:    result.add_bool(_("Adapt Speed"), &get_path()->m_adapt_speed, {}, {});
334:    result.add_int(_("Starting Node"), &m_starting_node, "starting-node", 0, 0U);
335:    result.add_path_handle(_("Handle"), m_path_handle, "handle");
336:  }
337:
338:  result.add_script(get_uid(), _("Collect script"), &m_collect_script, "collect-script");
339:
340:  result.reorder({"collect-script", "path-ref"});
341:
342:  return result;
343:}
